import { ChangeDetectionStrategy, Component, computed, inject, input, signal } from '@angular/core';
import { SafeHtml } from '@angular/platform-browser';
import { MODULE_NAME } from 'espd-common/config';
import { SettingService, SettingType } from 'espd-common/setting';

@Component({
	selector: 'espd-footer',
	template: '<div [innerHtml]="customFooter()"></div>',
	changeDetection: ChangeDetectionStrategy.OnPush
})
export class FooterComponent {
	customFooterSetting = signal<string>('');
	customFooterOverride = input<SafeHtml>();
	customFooter = computed(() => this.customFooterOverride() ?? this.customFooterSetting());

	constructor() {
		const settingService = inject(SettingService);
		settingService.waitFor(MODULE_NAME).subscribe(() => {
			this.customFooterSetting.set((settingService.get(SettingType.CUSTOM_FOOTER) as string | undefined) ?? '');
		});
	}
}